--
-- Table structure for table `projects`
--

DROP TABLE IF EXISTS `projects`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `projects` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_code` varchar(20) NOT NULL,
  `name` varchar(200) NOT NULL,
  `description` text DEFAULT NULL,
  `location` varchar(255) DEFAULT NULL,
  `district` varchar(20) DEFAULT NULL,
  `contractor_id` int(11) DEFAULT NULL,
  `budget` decimal(15,2) DEFAULT 0.00,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `progress` tinyint(3) unsigned DEFAULT 0 COMMENT '0-100 percent',
  `status` enum('draft','endorsed','returned','planning','approved','bidding','awarded','assigned','active','delayed','on_hold','completion_inspection','completed','turnover','cancelled') DEFAULT 'draft',
  `created_by` int(11) DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `rejection_reason` text DEFAULT NULL,
  `engineering_reviewed_by` int(11) DEFAULT NULL,
  `engineering_reviewed_at` datetime DEFAULT NULL,
  `engineering_remarks` text DEFAULT NULL,
  `ntp_issued_by` int(11) DEFAULT NULL,
  `ntp_issued_at` datetime DEFAULT NULL,
  `ntp_notes` text DEFAULT NULL,
  `completion_inspected_by` int(11) DEFAULT NULL,
  `completion_inspected_at` datetime DEFAULT NULL,
  `completion_remarks` text DEFAULT NULL,
  `turnover_by` int(11) DEFAULT NULL,
  `turnover_at` datetime DEFAULT NULL,
  `turnover_office` varchar(180) DEFAULT NULL,
  `turnover_notes` text DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `category` enum('Roads and Bridges','Drainage and Flood Control','Water Supply','Public Buildings and Facilities','Street Lighting','Parks and Recreation','Other') DEFAULT NULL,
  `funding_source` enum('LGU General Fund','20% Development Fund','National Government Fund','Grant/Donor Fund','Special Education Fund','Other') DEFAULT NULL,
  `implementing_office` varchar(150) DEFAULT NULL,
  `physical_target` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `project_code` (`project_code`),
  KEY `idx_projects_status` (`status`),
  KEY `idx_projects_contractor` (`contractor_id`),
  CONSTRAINT `projects_ibfk_1` FOREIGN KEY (`contractor_id`) REFERENCES `contractors` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `projects`
--

LOCK TABLES `projects` WRITE;
/*!40000 ALTER TABLE `projects` DISABLE KEYS */;
INSERT INTO `projects` VALUES (1,'PRJ-001','Elevated Landscape Promenade – Quezon Memorial Circle to Ninoy Aquino Parks and Wildlife','A landscaped, pedestrian- and bike-friendly elevated overpass built above Elliptical Road, linking Quezon Memorial Circle to the Ninoy Aquino Parks and Wildlife Center. Built by the Quezon City Engineering Department (QCDE) and the Parks Development and Administration Department (PDAD) in partnership with the DENR, featuring bike ramps, seating, ambient lighting, and a sculptural pergola. Construction began April 2024 and the promenade was inaugurated by Mayor Joy Belmonte on November 11, 2025.','Elliptical Road, Barangay Central, District 4, Quezon City',NULL,NULL,180000000.00,'2024-04-01','2025-11-11',100,'turnover',2,23,'2024-03-01 00:00:00',NULL,4,'2024-02-15 00:00:00',NULL,4,'2024-04-01 00:00:00',NULL,4,'2025-11-05 00:00:00',NULL,2,'2025-11-11 00:00:00','Parks Development and Administration Department (PDAD)',NULL,14.6512000,121.0494000,'Parks and Recreation','LGU General Fund','Quezon City Engineering Department (QCDE) / Parks Development and Administration Department (PDAD)','1 elevated pedestrian and bike overpass, approx. 350 linear meters','2026-07-21 12:06:20','2026-08-06 12:57:19'),(2,'PRJ-002','Barangay Santa Cruz Evacuation Center','A new evacuation center for Barangay Santa Cruz residents, completed as part of the 167 city-funded infrastructure projects Quezon City finished in 2025 (total value ₱5.6 billion citywide).','Barangay Santa Cruz, District 1, Quezon City',NULL,NULL,45000000.00,'2024-09-01','2025-08-15',100,'turnover',2,23,'2024-08-05 00:00:00',NULL,4,'2024-07-20 00:00:00',NULL,4,'2024-09-01 00:00:00',NULL,4,'2025-08-10 00:00:00',NULL,2,'2025-08-15 00:00:00','District 1 Office / Quezon City DRRMO',NULL,14.6474000,121.0089000,'Public Buildings and Facilities','20% Development Fund','Quezon City Engineering Department (QCDE)','1 multi-story barangay evacuation center','2026-07-21 12:06:20','2026-08-11 09:51:57'),(3,'PRJ-003','Quezon City Schools Division Office Building','New office building for the DepEd Quezon City Schools Division, completed and turned over among the 167 infrastructure projects the city government finished in 2025.','Barangay Ramon Magsaysay, District 1, Quezon City',NULL,NULL,120000000.00,'2024-01-15','2025-10-01',100,'turnover',2,23,'2023-12-10 00:00:00',NULL,4,'2023-11-20 00:00:00',NULL,4,'2024-01-15 00:00:00',NULL,4,'2025-09-20 00:00:00',NULL,2,'2025-10-01 00:00:00','DepEd Quezon City Schools Division',NULL,14.6620000,121.0210000,'Public Buildings and Facilities','Special Education Fund','Quezon City Schools Division Office / Quezon City Engineering Department (QCDE)','1 new DepEd Schools Division Office building','2026-07-21 12:06:20','2026-07-21 12:06:20'),(4,'PRJ-004','Amoranto Sports Complex Swimming Pool Rehabilitation','Rehabilitation of the swimming pool at the Amoranto Sports Complex, completed as part of the city\'s 2025 infrastructure program.','Barangay N.S. Amoranto (Gintong Silahis), District 1, Quezon City',NULL,NULL,35000000.00,'2025-01-15','2025-09-30',100,'turnover',2,23,'2024-12-10 00:00:00',NULL,4,'2024-11-25 00:00:00',NULL,4,'2025-01-15 00:00:00',NULL,4,'2025-09-22 00:00:00',NULL,2,'2025-09-30 00:00:00','Parks Development and Administration Department (PDAD)',NULL,14.6390000,120.9960000,'Parks and Recreation','LGU General Fund','Parks Development and Administration Department (PDAD)','1 rehabilitated competition swimming pool and deck','2026-07-21 12:06:20','2026-07-21 12:06:20'),(5,'PRJ-005','Social Services Development Department Dry Storage Warehouse','A dry storage warehouse for the Social Services Development Department (SSDD) in Payatas, completed in 2025 to support relief-goods and supplies storage for the district.','Barangay Payatas, District 2, Quezon City',NULL,NULL,28000000.00,'2025-02-01','2025-08-20',100,'turnover',2,23,'2025-01-10 00:00:00',NULL,4,'2024-12-15 00:00:00',NULL,4,'2025-02-01 00:00:00',NULL,4,'2025-08-12 00:00:00',NULL,2,'2025-08-20 00:00:00','Social Services Development Department (SSDD)',NULL,14.7160000,121.1050000,'Public Buildings and Facilities','LGU General Fund','Social Services Development Department (SSDD)','1 dry storage warehouse facility','2026-07-21 12:06:20','2026-07-21 12:06:20'),(6,'PRJ-006','Krus na Ligas Health Center Retrofit','Retrofitting and rehabilitation of the Krus na Ligas Health Center, serving residents of Barangay Krus na Ligas, U.P. Campus, and Teachers\' Village West (approx. 73,647 residents). Turned over to the city government after a 13-week rehabilitation.','Barangay Krus na Ligas, District 4, Quezon City',NULL,NULL,12000000.00,'2025-05-01','2025-08-03',100,'turnover',2,23,'2025-04-10 00:00:00',NULL,4,'2025-03-25 00:00:00',NULL,4,'2025-05-01 00:00:00',NULL,4,'2025-07-28 00:00:00',NULL,2,'2025-08-03 00:00:00','Quezon City Health Department',NULL,14.6550000,121.0670000,'Public Buildings and Facilities','20% Development Fund','Quezon City Health Department / Quezon City Engineering Department (QCDE)','1 retrofitted barangay health center','2026-07-21 12:06:20','2026-07-21 12:06:20'),(7,'PRJ-007','Elliptical Road Sidewalk and Bike Lane Rehabilitation','Rehabilitation of sidewalks and bike lanes along Elliptical Road around Quezon Memorial Circle, improving pedestrian and cyclist safety. Completed as part of the city\'s 2025 infrastructure program.','Elliptical Road, Barangay Bagong Pag-asa, District 1, Quezon City',NULL,NULL,60000000.00,'2024-11-01','2025-06-30',100,'turnover',2,23,'2024-10-05 00:00:00',NULL,4,'2024-09-20 00:00:00',NULL,4,'2024-11-01 00:00:00',NULL,4,'2025-06-22 00:00:00',NULL,2,'2025-06-30 00:00:00','Quezon City Engineering Department (QCDE)',NULL,14.6530000,121.0455000,'Roads and Bridges','LGU General Fund','Quezon City Engineering Department (QCDE)','Sidewalk and bike lane rehabilitation, full Elliptical Road loop','2026-07-21 12:06:20','2026-07-21 12:06:20'),(8,'PRJ-008','G. Araneta Avenue Flood Mitigation Structure (San Juan River)','Expansion of the drainage system along G. Araneta Avenue, replacing the previous 36-inch drainage pipe with two 1.5-meter pipes, plus a new pumping station. DPWH, San Miguel Corporation, and the MMDA are jointly dredging the adjoining San Juan River. Originally targeted for completion in February 2026; the pumping station component is behind schedule.','G. Araneta Avenue, Barangay Santo Domingo (Matalahib), District 1, Quezon City',NULL,NULL,320000000.00,'2025-03-01','2026-10-31',68,'delayed',2,23,'2025-02-05 00:00:00',NULL,4,'2025-01-15 00:00:00',NULL,4,'2025-03-01 00:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14.6270000,121.0100000,'Drainage and Flood Control','National Government Fund','Department of Public Works and Highways (DPWH) - NCR / Metro Manila Development Authority (MMDA)','2 x 1.5-meter box drainage lines + 1 pumping station','2026-07-21 12:06:20','2026-07-21 12:06:20'),(9,'PRJ-009','Kabayani Street–Matandang Balara Bridge','A bridge across the Marikina River linking Barangay Matandang Balara, Quezon City to Barangay Malanday, Marikina City — part of a 3-bridge package across the Marikina River funded by a $175.1-million ADB loan. Construction has run well past its original 2026 target completion date.','Barangay Matandang Balara, District 3, Quezon City (river crossing to Brgy. Malanday, Marikina City)',NULL,NULL,3200000000.00,'2022-06-01','2027-06-30',100,'completed',2,23,'2022-04-15 00:00:00',NULL,4,'2022-03-01 00:00:00',NULL,4,'2022-06-01 00:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14.6650000,121.0850000,'Roads and Bridges','Grant/Donor Fund','Department of Public Works and Highways (DPWH) - ADB-Assisted Bridges Program','1 river-crossing bridge with approach roads','2026-07-21 12:06:20','2026-08-09 13:03:09'),(10,'PRJ-010','Quezon City Solarization Program – City Hall, QC General Hospital & Public Schools','Citywide solarization program by the Quezon City Department of Engineering (QCDE), installing rooftop solar across Quezon City Hall, Quezon City General Hospital, and 35 public school buildings. Of the 3.9 MWp target, 2.9 MWp has been energized so far, projected to save at least ₱40 million annually.','Quezon City Hall, Barangay Central, District 4, Quezon City',NULL,NULL,220000000.00,'2024-06-01','2026-12-31',74,'active',2,23,'2024-05-01 00:00:00',NULL,4,'2024-04-10 00:00:00',NULL,4,'2024-06-01 00:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14.6488000,121.0509000,'Other','LGU General Fund','Quezon City Department of Engineering (QCDE) / General Services Department','Rooftop solar PV, 3.9 MWp target across City Hall, QC General Hospital, and 35 schools','2026-07-21 12:06:20','2026-08-10 06:02:34'),(11,'PRJ-011','Elevated Evacuation Center – Barangay Tatalon','One of three multi-level evacuation centers Quezon City is building in flood-prone barangays (Tatalon, Santo Domingo, Silangan), with a rooftop basketball court and capacity for informal-settler families, part-funded through the DBM Informal Settlers Fund.','Barangay Tatalon, District 4, Quezon City',NULL,NULL,65000000.00,'2025-06-01','2026-12-31',45,'active',2,23,'2025-05-05 00:00:00',NULL,4,'2025-04-10 00:00:00',NULL,4,'2025-06-01 00:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14.6270000,121.0330000,'Public Buildings and Facilities','National Government Fund','Quezon City Engineering Department (QCDE) / DSWD Quezon City','1 multi-level evacuation center, rooftop basketball court','2026-07-21 12:06:20','2026-07-21 12:06:20'),(12,'PRJ-012','Elevated Evacuation Center – Barangay Santo Domingo','One of three multi-level evacuation centers Quezon City is building in flood-prone barangays (Tatalon, Santo Domingo, Silangan), with a rooftop basketball court and capacity for informal-settler families, part-funded through the DBM Informal Settlers Fund.','Barangay Santo Domingo (Matalahib), District 1, Quezon City',NULL,NULL,65000000.00,'2025-07-01','2027-01-31',38,'active',2,23,'2025-06-01 00:00:00',NULL,4,'2025-05-10 00:00:00',NULL,4,'2025-07-01 00:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14.6300000,121.0120000,'Public Buildings and Facilities','National Government Fund','Quezon City Engineering Department (QCDE) / DSWD Quezon City','1 multi-level evacuation center, rooftop basketball court','2026-07-21 12:06:20','2026-07-21 12:06:20'),(13,'PRJ-013','DPWH 4-Storey Evacuation Center – Barangay Fairview','A completed 4-storey evacuation center built by the DPWH in Barangay Fairview, adding permanent disaster-response shelter capacity to the Novaliches district.','Barangay Fairview, District 5, Quezon City',NULL,NULL,55000000.00,'2023-02-01','2024-06-01',100,'turnover',2,23,'2023-01-10 00:00:00',NULL,4,'2022-12-05 00:00:00',NULL,4,'2023-02-01 00:00:00',NULL,4,'2024-05-20 00:00:00',NULL,2,'2024-06-01 00:00:00','Quezon City DRRMO',NULL,14.7333000,121.0500000,'Public Buildings and Facilities','National Government Fund','Department of Public Works and Highways (DPWH)','1 four-storey evacuation center','2026-07-21 12:06:20','2026-07-21 12:06:20'),(14,'PRJ-014','Pumping Station – Boundary of Barangay Santa Cruz and Barangay Mariblo','One of two identical DPWH-funded pumping stations (₱282 million each) proposed for the boundary of Barangay Santa Cruz and Barangay Mariblo, part of the 331 DPWH flood-control projects implemented in Quezon City since 2022 (~₱17 billion total). Flagged and returned by the Quezon City Engineering Department for non-compliance with the city\'s drainage master plan — as the department noted, pumping floodwater from one location to another does not resolve flooding in a non-coastal area, it simply displaces the problem. No certificate of coordination was issued by the city government.','Boundary of Barangay Santa Cruz and Barangay Mariblo, District 1, Quezon City',NULL,13,282000000.00,'2024-01-01',NULL,10,'returned',2,NULL,NULL,NULL,4,'2025-09-10 00:00:00','Non-compliant with the City\'s drainage master plan; no certificate of coordination issued. Pumping floodwater from one location to another does not resolve flooding in a non-coastal area, it merely displaces the problem elsewhere.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14.6480000,121.0093000,'Drainage and Flood Control','National Government Fund','Department of Public Works and Highways (DPWH) - NCR','1 flood pumping station','2026-07-21 12:06:20','2026-07-21 12:06:20'),(15,'PRJ-015','Quezon City Intermodal Transport Terminal and Depot','A planned intermodal rail-city bus terminal and depot for Quezon City, discussed by the MMDA, DOTr, GSIS, and the Quezon City government (coordination meeting held October 15, 2024), targeted for completion by 2027.','Barangay Bagong Pag-asa, District 1, Quezon City',NULL,NULL,3500000000.00,NULL,'2027-12-31',5,'planning',2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,14.6570000,121.0330000,'Other','National Government Fund','Quezon City Government / MMDA / DOTr (Joint Coordination)','1 intermodal rail-city bus terminal and depot','2026-07-21 12:06:20','2026-08-12 02:29:54'),(18,'PRJ-016','Elliptical Road Detention Basin','Underground stormwater detention basin along Elliptical Road — one of four detention basins built by DPWH and Quezon City in the city\'s most flood-prone corridors (Elliptical Road, Banawe Street, E. Rodriguez Avenue-Amoranto Street, and Commonwealth Avenue-Don Antonio Drive) to temporarily hold stormwater and reduce road flooding during heavy rain.','Elliptical Road, Barangay Bagong Pag-asa, District 1, Quezon City','District 1',1,185000000.00,'2025-03-01','2026-11-30',58,'active',2,23,'2025-02-04 00:00:00',NULL,4,'2025-02-19 00:00:00',NULL,4,'2025-02-27 00:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Drainage and Flood Control','National Government Fund','DPWH - Quezon City 2nd District Engineering Office','1 underground detention basin with pump station, approx. 5,000 cu.m. capacity','2026-08-11 10:12:10','2026-08-11 10:12:10'),(19,'PRJ-017','Banawe Street Detention Basin','Stormwater detention basin along Banawe Street, part of DPWH and Quezon City\'s network of flood-mitigation detention basins in chronically flooded corridors.','Banawe Street, Barangay Santo Domingo (Matalahib), District 1, Quezon City','District 1',2,162000000.00,'2025-05-01','2027-01-31',37,'active',2,23,'2025-04-06 00:00:00',NULL,4,'2025-04-21 00:00:00',NULL,4,'2025-04-29 00:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Drainage and Flood Control','National Government Fund','DPWH - Quezon City 2nd District Engineering Office','1 underground detention basin with pump station','2026-08-11 10:12:10','2026-08-11 10:12:10'),(20,'PRJ-018','E. Rodriguez Avenue–Amoranto Street Detention Basin','Stormwater detention basin at the E. Rodriguez Avenue-Amoranto Street junction, addressing recurring flash flooding in the area during the monsoon season.','E. Rodriguez Avenue corner Amoranto Street, Barangay N.S. Amoranto (Gintong Silahis), District 1, Quezon City','District 1',3,198000000.00,'2025-01-15','2026-10-15',66,'active',2,23,'2024-12-21 00:00:00',NULL,4,'2025-01-05 00:00:00',NULL,4,'2025-01-13 00:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Drainage and Flood Control','National Government Fund','DPWH - Quezon City 2nd District Engineering Office','1 underground detention basin with pump station','2026-08-11 10:12:11','2026-08-11 10:12:11'),(21,'PRJ-019','Commonwealth Avenue–Don Antonio Drive Detention Basin','Stormwater detention basin at Commonwealth Avenue corner Don Antonio Drive, part of the citywide detention-basin network targeting the most flood-prone intersections.','Commonwealth Avenue corner Don Antonio Drive, Barangay Commonwealth, District 2, Quezon City','District 2',4,172000000.00,'2025-04-01','2026-12-31',44,'active',2,23,'2025-03-07 00:00:00',NULL,31,'2025-03-22 00:00:00',NULL,31,'2025-03-30 00:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Drainage and Flood Control','National Government Fund','DPWH - Quezon City 2nd District Engineering Office','1 underground detention basin with pump station','2026-08-11 10:12:11','2026-08-11 10:12:11'),(22,'PRJ-020','New Kamuning Public Market','Redevelopment of the Kamuning Public Market into a modern, weather-protected public market facility — one of the 167 city infrastructure projects (worth a combined PHP5.6 billion) completed in 2025.','Kamuning Road, Barangay Kamuning, District 4, Quezon City','District 4',5,210000000.00,'2024-02-01','2025-10-01',100,'turnover',2,23,'2024-01-07 00:00:00',NULL,43,'2024-01-22 00:00:00',NULL,43,'2024-01-30 00:00:00',NULL,43,'2025-09-26 00:00:00','Inspected and accepted — meets contract specifications.',2,'2025-10-08 00:00:00','Public Market Administration Office',NULL,NULL,NULL,'Public Buildings and Facilities','LGU General Fund','Quezon City General Services Department','1 multi-level public market building with vendor stalls, cold storage, and parking','2026-08-11 10:12:11','2026-08-11 10:12:11'),(23,'PRJ-021','Bahay Modernismo Rehabilitation','Rehabilitation of Bahay Modernismo, a heritage modernist house inside the Quezon Memorial Circle, restored as a cultural and exhibit space — part of the 167 city infrastructure projects completed in 2025.','Quezon Memorial Circle, Barangay Central, District 4, Quezon City','District 4',1,42000000.00,'2024-06-01','2025-09-15',100,'turnover',2,23,'2024-05-07 00:00:00',NULL,43,'2024-05-22 00:00:00',NULL,43,'2024-05-30 00:00:00',NULL,43,'2025-09-10 00:00:00','Inspected and accepted — meets contract specifications.',2,'2025-09-22 00:00:00','Parks Development and Administration Department (PDAD)',NULL,NULL,NULL,'Public Buildings and Facilities','LGU General Fund','Quezon City Parks Development and Administration Department (PDAD)','1 rehabilitated heritage structure with exhibit galleries','2026-08-11 10:12:11','2026-08-11 10:12:11'),(24,'PRJ-022','Rosario Maclang Bautista General Hospital New Facilities','New patient-care facilities at Rosari